#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.hookshot_Skin)]
    public class Hookshot_Skin : EntityBehaviourDefinition
    {
        public Hookshot_Skin(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            UpdateModel(entity);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            UpdateModel(entity);
        }
        private void UpdateModel(Entity entity)
        {
            if (!entity.Parent.ExistsAndAlive())
            {
                entity.Remove();
                return;
            }
            entity.SetModelProperty("Source", entity.Position);
            entity.SetModelProperty("Dest", HookshotUserBuff.GetHookGunPoint(entity.Parent));
            entity.SetAnimationBool("Caught", Hookshot.IsCaught(entity));

            var vel = entity.Position - HookshotUserBuff.GetHookGunPoint(entity.Parent);
            entity.RenderRotation = Vector3.forward * Vector2.SignedAngle(Vector2.right, vel);
        }
    }
}